import{_ as e,c as o,o as n,ae as r}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"Ribbon Element (Pro)","description":"Ribbon Element (Pro)","frontmatter":{"title":"Ribbon Element (Pro)","description":"Ribbon Element (Pro)"},"headers":[],"relativePath":"guide/drag-drop-elements/ribbon-element.md","filePath":"guide/drag-drop-elements/ribbon-element.md"}'),a={name:"guide/drag-drop-elements/ribbon-element.md"};function i(l,t,d,s,b,c){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="ribbon-element-pro" tabindex="-1">Ribbon Element (Pro) <a class="header-anchor" href="#ribbon-element-pro" aria-label="Permalink to &quot;Ribbon Element (Pro)&quot;">​</a></h1><p>A ribbon or badge highlights a particular table column, especially if the product is on sale. Ninja Tables offers a Ribbon Element in the Drag and Drop builder that makes your pricing or product table stand out. Ribbons or badges are used in pricing tables to highlight sales items, top products, or small texts. Ninja Tables offer 4 types of ribbons- Side, Bookmark, Corner, and Horizontal. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Ribbon-element-in-table-1024x681.png" alt="Ribbon element in table"> Let’s see how it works.</p><h2 id="properties-of-ribbon-element" tabindex="-1"><strong>Properties of Ribbon Element</strong> <a class="header-anchor" href="#properties-of-ribbon-element" aria-label="Permalink to &quot;**Properties of Ribbon Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>General</td><td>Ribbon type</td><td>Side, Bookmark, Corner, and Horizontal</td></tr><tr><td></td><td>Ribbon Position</td><td>Left and Right</td></tr><tr><td></td><td>Ribbon Width</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Ribbon Height</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>X Offset</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Y Offset</td><td>Numeric Value, drag bar</td></tr><tr><td>Text</td><td>Ribbon Text</td><td>Text Field, drag bar</td></tr><tr><td></td><td>Font Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Font X Offset</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Font Y Offset</td><td>Numeric Value, drag bar</td></tr><tr><td>Background</td><td>Background Color</td><td>Graphical Color Selection</td></tr></tbody></table><h3 id="general" tabindex="-1"><strong>General</strong> <a class="header-anchor" href="#general" aria-label="Permalink to &quot;**General**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Ribbon-element-1024x554.png" alt="Ribbon element"></p><ul><li><strong>Ribbon type:</strong> Change the ribbon type to position in a corner or a rectangular format. By default, it is set to corner.</li><li>**Ribbon Position: **You can position the Ribbon on either Left or Right for a Corner ribbon.</li><li><strong>Ribbon Width:</strong> You can change the width of the ribbon.</li><li><strong>Ribbon Height:</strong> You can change the height of the ribbon.</li><li><strong>X Offset:</strong> You can change the X offset to move the ribbon horizontally. Available for bookmark and corner types.</li><li><strong>Y Offset:</strong> You can change the Y offset, which means moving the ribbon vertically. By default, it is set to -11.</li></ul><h3 id="text" tabindex="-1"><strong>Text</strong> <a class="header-anchor" href="#text" aria-label="Permalink to &quot;**Text**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Ribbon-text-1024x381.png" alt="Ribbon text"></p><ul><li><strong>Ribbon Text:</strong> You can change the text color of the ribbon.</li><li><strong>Font Color</strong>: You can change the color of the text. By default, it is set to Black.</li><li><strong>Font Size</strong>: You can change the size of the text. By default, it is set to 15.</li><li><strong>Font X Offset:</strong> You can change the X offset of the Font, which means you can move the Text of the ribbon horizontally.</li><li><strong>Font Y Offset:</strong> You can change the Y offset of the Font, which means you can move the Text of the ribbon vertically.</li><li><strong>Font Style</strong>: Change font style to bold, italic, or underlined.</li></ul><h3 id="background" tabindex="-1"><strong>Background</strong> <a class="header-anchor" href="#background" aria-label="Permalink to &quot;**Background**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Ribbon-background-color-1024x488.png" alt="Ribbon background color"><strong>Background Color:</strong> You can change the background color of the ribbon.</p><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>If a cell or column has a ribbon or badge, it shows the item is on sale or is an exclusive product. The ribbon element in Ninja Tables drag and drop mode helps you create visually appealing pricing and product tables. Let us know your thoughts and questions in the comment box.</p>',14)])])}const u=e(a,[["render",i]]);export{g as __pageData,u as default};
